-- ---- td_nnct_oa_document ----
UPDATE ecos_demo.td_nnct_oa_document SET "mobile_template_code" = '{
  template: `
    <div class="doc-paper-container">
        <div class="flowName"> {{ payload.paper.fileName }}</div>   
      <div>印发日期：{{ payload.formData.printedDate | formatTimestamp(''yyyy-MM-dd'')}}</div>      
      <table class="table-paper" style="margin-bottom:2px">
        <tr>
          <th width="120">发文字号</th>
          <td>
              <span v-if="payload.formData.docName">
                {{ payload.formData.docName }}〔{{ payload.formData.docYear }}〕{{ payload.formData.docCode }}号
              </span>
          </td>
          </tr>       
        <tr>
          <th >密级</th>
          <td>
          </td>
        </tr>       
        <tr>
          <th>标题</th>
          <td>{{ payload.formData.title }}</td>   
          </tr>
        <tr>
          <th>正文</th>
          <td >
           <upload-file :editable="isCanEditField(''originalFile'')" :disabled="!isCanEditField(''originalFile'')" :showUploadBar="false" title-class="fs14" :upload-file-list="payload.formData.originalFile"></upload-file>
          </td>
        </tr>
        <tr>
          <th>相关附件</th>
          <td >
             <template v-if="payload.formData && payload.formData.enclosure && payload.formData.enclosure.length">               
                 <upload-file  :editable="isCanEditField(''enclosure'')" :disabled="!isCanEditField(''enclosure'')" :showUploadBar="false" title-class="fs14" :upload-file-list="payload.formData.enclosure"></upload-file>       
              </template>
          </td>
        </tr>
        <tr>
          <th>关联流程</th>
          <td >
          <relate-flow-list v-if="payload.formData && payload.formData.relateFlowList && payload.formData.relateFlowList.length" :itemData="payload.formData.relateFlowList"/></td>
          </tr>
          <tr>     
         <th>公开情况</th>
          <td><div v-if="payload.formData.publicityType===''501''">[{{payload.formData.publicityType===''501''?''√'':''  ''}}] 主动公开</div><div v-if="payload.formData.publicityType===''502''">[{{payload.formData.publicityType===''502''?''√'':''  ''}}] 依申请公开</div><div v-if="payload.formData.publicityType===''503''">[{{payload.formData.publicityType===''503''?''√'':''  ''}}] 不予公开</div></td>
        </tr>
        <tr v-if="payload.formData.publicityType===''502''">
          <th>依申请公开理由</th>
          <td>{{payload.formData.publicityReason}}</td>
        </tr>
        <tr  v-if="payload.formData.publicityType===''503''">
          <th>依申请公开理由</th>
          <td >{{payload.formData.privateReason}}</td>
        </tr>
        <tr v-if="false">    
          
          <th>是否需要部门副经理初审</th>
          <td>{{ payload.formData&&payload.formData.isNeedBmfjl==''1''?''是'':'''' }}
              {{ payload.formData&&payload.formData.isNeedBmfjl==''0''?''否'':'''' }}
          </td>
          <th>部门副经理</th>
          <td>  <user-view-list :list="payload.formData.deptFjl"></user-view-list>
          </td>
          
        </tr>
        <tr v-if="false">               
          <th>是否需要相关部门会签</th>
          <td>{{ payload.formData&&payload.formData.isNeedDept==''1''?''是'':'''' }}
              {{ payload.formData&&payload.formData.isNeedDept==''0''?''否'':'''' }}
          </td>
          <th>相关部门会签人</th>
          <td>
           <template v-if="payload.formData&&payload.formData.deptHandleUserList && payload.formData.deptHandleUserList.length">
           <user-view-list :list="payload.formData.deptHandleUserList"></user-view-list>
           </template>
          </td>
          
        </tr>
         <tr v-if="false"> 
         
          <th>分管领导</th>
          <td >
           <template v-if="payload.formData&&payload.formData.fgldList && payload.formData.fgldList.length">
           <user-view-list :list="payload.formData.fgldList"></user-view-list>    
         
           </template>
          </td>
          
        </tr>       
       
         
        <tr>
         <th>董事长签发</th>
          <td >
          <flow-operate-remark-item :list="dszList"></flow-operate-remark-item>
          </td>
        </tr>
        <tr>
         <th>总经理审批</th>
          <td >   
          <flow-operate-remark-item :list="zjlList"></flow-operate-remark-item> 
          </td>
        </tr>
        <tr>
         <th>分管领导审批</th>
          <td >        
          <flow-operate-remark-item :list="fgldList"></flow-operate-remark-item> 
          </td>
        </tr> 
         
