  data(){
    return {
        // 集团领导列表信息
      orgLeaderObj:{}
    }
  },
  created(){
    // 获取集团领导列表
    this.loadOrgLeaderDept();
  },
  methods: {
     loadOrgLeaderDept(){
       // 获取集团领导列表
      this.$http
      .post("/systembasedata/user/list", {pageNum: 0,
      pageSize: 1000,queryParameter:{
      companyId: "277562193757818880"
      }})
      .success(e => {
     
      let userObj = {}
      if(e&&e.length){
        e.forEach(user=>{
          userObj[user.id] = user
        })
      }
      this.orgLeaderObj = userObj
       console.log("++orgLeaderObj+++",this.orgLeaderObj)
        // this.initParam()
      })
      .failure(() => {})
    },
    getDateString(date){
      if(date){
        var time = new Date(date);
        var y = time.getFullYear();
        var m = time.getMonth()+1;
        var d = time.getDate();
        var h = time.getHours();
        var mm = time.getMinutes();
        var s = time.getSeconds();
        return y+''-''+this.add0(m)+''-''+this.add0(d);
      }
      return date
    },    
    add0(m){return m<10?''0''+m:m },
    getHistoryCurrent(nodeSign, nodeSign1 = false, nodeSign2 = false) {
      // 增加通讯录排序的办理意见列表
      // tslint-disable
      // eslint-disable
      // tslint:disable-line
      // eslint-disable-next-line @typescript-eslint/ban-ts-comment
      // @ts-ignore
      const fc = this.flowContext || {},
        list = fc.handleHistoryList || [],
        latestOpinions = {}
      // console.log("-----------code getHistory-----------")
      for (let i = 0, len = list.length; i < len; i++) {
        let opinion = list[i]
        
        if(this.orgLeaderObj[opinion.handleUserId]){
          opinion.sortNum = this.orgLeaderObj[opinion.handleUserId].sortNum
        }
        if (opinion.nodeSign === nodeSign) {
          
          const userId = opinion.handleUserId
          // tslint-disable
          // eslint-disable
          // tslint:disable-line
          // eslint-disable-next-line @typescript-eslint/ban-ts-comment
          // @ts-ignore
          if (!(userId in latestOpinions) || opinion.handleTime > latestOpinions[userId].handleTime) {
            // tslint-disable
            // eslint-disable
            // tslint:disable-line
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            // @ts-ignore
            latestOpinions[userId] = opinion
          }
        }
        // tslint-disable
        // eslint-disable
