  created(){
    // 获取集团领导列表
    this.loadOrgLeaderDept();
  },
  methods: {
     loadOrgLeaderDept(){
       // 获取集团领导列表
      this.$http
      .post("/systembasedata/user/list", {pageNum: 0,
      pageSize: 1000,queryParameter:{
      companyId: "277562193757818880"
      }})
      .success(e => {
     
      let userObj = {}
      if(e&&e.length){
        e.forEach(user=>{
          userObj[user.id] = user
        })
      }
      this.orgLeaderObj = userObj
       console.log("++orgLeaderObj+++",this.orgLeaderObj)
        // this.initParam()
      })
      .failure(() => {})
    },
    getDateString(date){
      if(date){
        var time = new Date(date);
        var y = time.getFullYear();
        var m = time.getMonth()+1;
        var d = time.getDate();
        var h = time.getHours();
        var mm = time.getMinutes();
        var s = time.getSeconds();
        return y+''-''+this.add0(m)+''-''+this.add0(d);
      }
      return date
    },    
    add0(m){return m<10?''0''+m:m },
    getHistoryCurrent(nodeSign, nodeSign1 = false, nodeSign2 = false) {
      // 增加通讯录排序的办理意见列表
      // tslint-disable
      // eslint-disable
      // tslint:disable-line
      // eslint-disable-next-line @typescript-eslint/ban-ts-comment
      // @ts-ignore
      const fc = this.flowContext || {},
        list = fc.handleHistoryList || [],
        latestOpinions = {}
      // console.log("-----------code getHistory-----------")
      for (let i = 0, len = list.length; i < len; i++) {
        let opinion = list[i]
        
        if(this.orgLeaderObj[opinion.handleUserId]){
          opinion.sortNum = this.orgLeaderObj[opinion.handleUserId].sortNum
        }
        if (opinion.nodeSign === nodeSign) {
          
          const userId = opinion.handleUserId
          // tslint-disable
          // eslint-disable
          // tslint:disable-line
          // eslint-disable-next-line @typescript-eslint/ban-ts-comment
          // @ts-ignore
          if (!(userId in latestOpinions) || opinion.handleTime > latestOpinions[userId].handleTime) {
            // tslint-disable
            // eslint-disable
            // tslint:disable-line
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            // @ts-ignore
            latestOpinions[userId] = opinion
          }
        }
        // tslint-disable
        // eslint-disable
        // tslint:disable-line
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-ignore
        if (nodeSign1 && nodeSign1.length) {
          if (opinion.nodeSign === nodeSign1) {
            const userId = opinion.handleUserId
            // tslint-disable
            // eslint-disable
            // tslint:disable-line
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            // @ts-ignore
            if (!(userId in latestOpinions) || opinion.handleTime > latestOpinions[userId].handleTime) {
              // tslint-disable
              // eslint-disable
              // tslint:disable-line
              // eslint-disable-next-line @typescript-eslint/ban-ts-comment
              // @ts-ignore
              latestOpinions[userId] = opinion
            }
          }
        }
        // tslint-disable
        // eslint-disable
        // tslint:disable-line
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-ignore
        if (nodeSign2 && nodeSign2.length) {
          if (opinion.nodeSign === nodeSign2) {
            const userId = opinion.handleUserId
            // tslint-disable
            // eslint-disable
            // tslint:disable-line
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            // @ts-ignore
            if (!(userId in latestOpinions) || opinion.handleTime > latestOpinions[userId].handleTime) {
              // tslint-disable
              // eslint-disable
              // tslint:disable-line
              // eslint-disable-next-line @typescript-eslint/ban-ts-comment
              // @ts-ignore
              latestOpinions[userId] = opinion
            }
          }
        }
      }
        console.log("+++latestOpinions",latestOpinions)
      // console.log("getHistory-----------", latestOpinions)
      return Object.values(latestOpinions)
    },
    getSelectTypeName(attrName) {
      const formData = this.payload.formData,
        fc = this.flowContext || {},      
        name = ""
        let fieldList = fc.payload&&fc.payload.fieldList?fc.payload.fieldList:[]
        fieldList = fieldList.length?fieldList:(fc.fieldList?fc.fieldList:[])
        console.log("fc",fc)
      for (let i = 0, len = fieldList.length; i < len; i++) {
        const item = fieldList[i]
        if (item.name === attrName) {
          const datasource = item.datasource || []
          for (let j = 0, len2 = datasource.length; j < len2; j++) {
            const data = datasource[j]
            if (attrName && data[item.valueField] === formData[attrName]) {
              return data[item.labelField]
            }
          }
        }
      }
      return formData[attrName]
    }
    
  },
  computed: {
    isCanSeeLeaderAttach() {
      let isCanSeeLeaderAttach = false,isCanRoleList=[''10000'',''130'',''110'',''100'',''officeUser''],roleList = this.flowContext&&this.flowContext.executor&&this.flowContext.executor.roleList?this.flowContext.executor.roleList:[]
      if(roleList&&roleList.length){
          roleList.forEach(role=>{
            if(isCanRoleList.indexOf(role)>-1){
              isCanSeeLeaderAttach = true              
            }
          })
      }
      if(this.flowContext&&this.flowContext.executor&&this.payload&&this.payload.formData&&this. payload.formData.creatorId===this.flowContext.executor.id){
        isCanSeeLeaderAttach =  true
      }
      if(!(this.payload&&this.payload.formData&&this.payload.formData.isCanSeeAttach==="1")){
        isCanSeeLeaderAttach = false
      }
      return isCanSeeLeaderAttach
    },
    // 所有领导意见
    allorgLeaderList(){
      let list = [].concat(this.dszList).concat(this.zjlList).concat(this.fgldList).concat(this.zjlzlList).concat(this.bgsFgldList) // 拼接领导意见
      list.sort(function(a,b){return a.sortNum-b.sortNum}); // 按照通讯录排序 升序
      console.log("allorgLeaderList",list)
      return list
    },
    // 拟办意见
    nbyjList(){
      let list = [].concat(this.lwdjList).concat(this.bgszrList)
      list.sort(function(a,b){return b.handleTime - a.handleTime});   // 按照办理时间排序 降序    
      return list
    },
    childDeptList(){
      let list = [].concat(this.bmblList).concat(this.bmyjList)
      list.sort(function(a,b){return b.handleTime - a.handleTime});   // 按照办理时间排序 降序    
      return list
    },
    ngbmList(){
       return this.getHistoryCurrent("ngbm")
    },
    lwdjList() {
      return this.getHistoryCurrent("lwdj")
    },
    startList() {
      return this.getHistoryCurrent("start")
    },
    bmblList() {			
      return this.getHistoryCurrent("bm_bl")
    },
    bmyjList() {
      return this.getHistoryCurrent("bm_yj")
    },    
    bgszrList() {
      return this.getHistoryCurrent("office_leader")
    },
    bgsFgldList() {
      return this.getHistoryCurrent("office_fgld")
    },
    zjlzlList() {
      return this.getHistoryCurrent("zjzlzl")
    },
    fgldList() {
      return this.getHistoryCurrent("other_fgld")
    },
    zjlList() {
      return this.getHistoryCurrent("zjl")
    },
    dszList() {
      return this.getHistoryCurrent("dsz")
    },
    dshList() {
      return this.getHistoryCurrent("dsh")
    },
    processedNgyj() {
      // 使用正则表达式找到所有的 <p> 标签，并添加内联样式
      return this.payload.formData.nbyj ? this.payload.formData.nbyj.replace(/<p(.*?)>/g, ''<p$1 style="margin: 0;">'') : '''';
    },
    yzList() {
      return this.getHistory("yz")
    },
  }
