UPDATE ecos_demo.td_nnct_oa_document SET "template_code" = '{
  template: `
    <div style="width: 1024px; display: block; margin: 0 auto 64px auto">
      <table class="table-paper" style="margin-bottom:2px">
       <tr>
          <th>文件标题名称</th>
          <td colspan="3">{{ payload.formData.title }}</td>
        </tr>
        <tr>
          <th>来文单位</th>
          <td colspan="3">{{ payload.formData.dispatchOrgName }}</td>
        </tr>
        <tr>
          <th>收文日期</th>
          <td colspan="3">{{ getDateString(payload.formData.receiveDate) }}</td>
        </tr>
        <tr>
          <th>正文</th>
          <td colspan="3">
            <attachment-list v-if="payload.formData.originDoc&&payload.formData.originDoc.length" :file-list="payload.formData.originDoc" />   
          </td>         
        </tr> 
         <tr>
          <th>相关附件</th>
          <td colspan="3">
            <attachment-list v-if="payload.formData.attachmentList&&payload.formData.attachmentList.length" :file-list="payload.formData.attachmentList" />   
          </td>         
        </tr> 
        
        <tr>
				  <th>关联流程</th>
				  <td colspan="3">
				    <template
					  	v-if="payload.formData && payload.formData.relateFlowList && payload.formData.relateFlowList.length">
					  	<relate-flow-list :itemData="payload.formData.relateFlowList" />
					  </template>
				  </td>
			  </tr>
        <tr>
          <th>备注</th>
          <td  colspan="3">{{ payload.formData.remark  }}</td>
        </tr>
        <tr>
          <th>收文登记<br>拟办意见</th>
          <td colspan="3" v-html="processedNgyj"></td>
        </tr> 
         <tr>
          <th>核稿意见</th>
          <td colspan="3">
            <flow-operate-remark-item :list="hgList"></flow-operate-remark-item> 
           
          </td>         
        </tr>
        <tr>
          <th>发起部门<br>负责人审核</th>
          <td colspan="3">
            <flow-operate-remark-item :list="bmfzrList"></flow-operate-remark-item> 
           
          </td>         
        </tr>
        <tr>
          <th>工会委员会<br>审核</th>
          <td colspan="3">
            <flow-operate-remark-item :list="ghwyhList"></flow-operate-remark-item> 
            
          </td>         
        </tr>
        <tr>
          <th>工会副主席<br>审核</th>
          <td colspan="3">
            <flow-operate-remark-item :list="ghfzxList"></flow-operate-remark-item> 
           
          </td>         
        </tr>
        <tr>
          <th>工会主席<br>审核</th>
          <td colspan="3">
            <flow-operate-remark-item :list="ghzxList"></flow-operate-remark-item> 
           
          </td>         
        </tr>
        <tr>
        <th>领导签阅意见</th>
          <td colspan="3">
          <flow-operate-remark-item :list="yzList"></flow-operate-remark-item>
          </td>         
        </tr>
        
        
            
      </table>     
    </div>`,
  data(){
    return {
    }
  },
  methods: {
    getDateString(date){
      if(date){
        var time = new Date(date);
        var y = time.getFullYear();
        var m = time.getMonth()+1;
        var d = time.getDate();
        var h = time.getHours();
        var mm = time.getMinutes();
        var s = time.getSeconds();
        return y+''-''+this.add0(m)+''-''+this.add0(d);
      }
      return date
    },    
    add0(m){return m<10?''0''+m:m },
    getHistory(nodeSign) {
      const fc = this.flowContext || {},
        list = fc.handleHistoryList || [],
        result = []
      if (!list.length) {
        return []
      }
      for (let i = 0, len = list.length; i < len; i++) {
        if (list[i].nodeSign === nodeSign) {
          result.push(list[i])
        }
       
      }
    
      return result
    }
  },
  computed: {
    hgList() {
      return this.getHistory("hg")
    },
    bmfzrList() {
      return this.getHistory("bmfzr")
    },
    ghwyhList() {
      return this.getHistory("ghwyh")
    },
    
    ghfzxList() {
      return this.getHistory("ghfzx")
    },
    ghzxList() {
      return this.getHistory("ghzx")
    },
    processedNgyj() {
      // 使用正则表达式找到所有的 <p> 标签，并添加内联样式
      return this.payload.formData.nbyj ? this.payload.formData.nbyj.replace(/<p(.*?)>/g, ''<p$1 style="margin: 0;">'') : '''';
    },
    yzList() {
      return this.getHistory("yz")
    },
    
  }
}' WHERE id = 23;
UPDATE ecos_demo.td_nnct_oa_document SET "template_code" = '{
    template: `
        <div style="width: 1024px; display: block; margin: 0 auto 64px auto">
        
            <table class="table-paper" style="margin-bottom:2px;">
                <tr>
                    <th>来文单位</th>
                    <td colspan="1.5">{{ payload.formData.dispatchOrgName }}</td>
                    <th>文号</th>
                    <td colspan="1.5" style="white-space:unset">
                        {{ payload.formData.receiveNumber }}
                    </td>
                </tr>
                
                <tr>
                    <th width="15%">文件名称</th>
                    <td colspan="3">{{ payload.formData.title }}</td>
                </tr>
                <tr>
                    <th>董事长批阅<br />意见</th>
                    <td colspan="3"><flow-operate-remark-item :list="dszList"></flow-operate-remark-item></td>
                </tr>
                <tr>
                    <th>总经理批阅<br />意见</th>
                    <td colspan="3"><flow-operate-remark-item :list="zjlList"></flow-operate-remark-item></td>
                </tr>
                <tr>
                    <th>分管领导审批<br />意见</th>
                    <td colspan="3"><flow-operate-remark-item :list="fgldList"></flow-operate-remark-item></td>
                </tr>
                <tr>
                    <th>部门审批意见</th>
                    <td colspan="3"><flow-operate-remark-item :list="bmList"></flow-operate-remark-item></td>
                </tr>
                
                <tr>
                    <th>拟办意见</th>
                    <td colspan="3" v-html="processedNgyj"></td>
                </tr>
                
                <tr>
                    <th>正文</th>
                    <td colspan="3">
                        <template
                            v-if="payload.formData && payload.formData.zw && payload.formData.zw.length">
                            <attachment-list :file-list="payload.formData.zw" />
                        </template>
                    </td>
                </tr>
                <tr>
                    <th>相关附件</th>
                    <td colspan="3">
                        <template
                            v-if="payload.formData && payload.formData.fj && payload.formData.fj.length">
                            <attachment-list :file-list="payload.formData.fj" />
                        </template>
                    </td>
                </tr>
                <tr>
                    <th>关联流程</th>
                    <td colspan="3">
                        <template
                            v-if="payload.formData && payload.formData.relateFlowList && payload.formData.relateFlowList.length">
                            <relate-flow-list :itemData="payload.formData.relateFlowList" />
                        </template>
                    </td>
                </tr>
                
                <tr>
                    <th>备注</th>
                    <td colspan="3">{{ payload.formData.remark }}</td>
                </tr>
            </table>
        </div>
    `,
                methods: {
                    formatTimestamp(timestamp) {
                        if (timestamp) {
                            var date = new Date(timestamp);
                            var year = date.getFullYear();
                            var month = date.getMonth() + 1;
                            var day = date.getDate();
                            return year + ''-'' + month + ''-'' + day;
                        }
                    },
                    getHistory(nodeSign) {
                        const fc = this.flowContext || {},
                            list = fc.handleHistoryList || [],
                            result = []
                        if (!list.length) {
                            return []
                        }
                        for (let i = 0, len = list.length; i < len; i++) {
                            if (list[i].nodeSign === nodeSign) {
                                result.push(list[i])
                            }
                        }
                        return result
                    }
                },
                computed: {
                    bmList() {
                        let list = [].concat(this.fzrList).concat(this.fjlList).concat(this.xgbmList)
                        return list
                    },
                    xgbmList() {
                        return this.getHistory("xgbm")
                    },
                    fjlList() {
                        return this.getHistory("fjl")
                    },
                    fzrList() {
                        return this.getHistory("fzr")
                    },
                    fgldList() {
                        return this.getHistory("fgld")
                    },
                    zjlList() {
                        return this.getHistory("zjl")
                    },
                    dszList() {
                        return this.getHistory("dsz")
                    },
                    processedNgyj() {
                      // 使用正则表达式找到所有的 <p> 标签，并添加内联样式
                      return this.payload.formData.processData ? this.payload.formData.processData.replace(/<p(.*?)>/g, ''<p$1 style="margin: 0;">'') : '''';
                    },
                },
    } 	' WHERE id = 30;
