UPDATE ecos_demo.td_nnct_oa_document SET "mobile_template_code" = '{
  template: `
    <div class="doc-paper-container">
        <div class="flowName"> {{ payload.paper.fileName }}</div>   
      <div>印发日期：{{ payload.formData.printedDate | formatTimestamp(''yyyy-MM-dd'')}}</div>      
      <table class="table-paper" style="margin-bottom:2px">Time | formatTimestamp("yyyy-MM-dd") }}</div>
        <table class="table-paper" style="margin-bottom:2px">       
        <tr>
            <th width="160" class="tc">标题</th>
            <td colspan="3" >{{ payload.formData.title }}</td>
        </tr>
       
        </tr>
        <tr>
            <th width="160" class="tc">相关附件</th>
            <td colspan="3"  >
                
					<template
						v-if="payload.formData && payload.formData.fj && payload.formData.fj.length">
						<upload-file :disabled="true" :showUploadBar="false" title-class="fs14"
							:upload-file-list="payload.formData.fj"></upload-file>
					</template>
            </td>
        </tr>
        <tr>
            <th width="160" class="tc">招标采购部门意见</th>
            <td colspan="3"  >
                <flow-operate-remark-item :list="zbcgyjList"></flow-operate-remark-item>
                
            </td>         
        </tr>
        <tr>
            <th width="160" class="tc">备注</th>
            <td colspan="3" >{{ payload.formData.bz }}</td>
        </tr>
      </table>
    </div>`,
  methods: {
    getSelectTypeName(attrName){      
      const formData=this.payload.formData,fc = this.flowContext || {},fieldList = fc.payload.fieldList,name=''''
      for (let i = 0, len = fieldList.length; i < len; i++) {
        let item = fieldList[i]
        if(item.name===attrName){
          const datasource = item.datasource||[]
          for (let j = 0, len2 = datasource.length; j < len2; j++) {
            let data = datasource[j]
            if(attrName&&data[item.valueField]===formData[attrName]){
             return data[item.labelField]              
            }
          }
        }
      }
      return formData[attrName]
    },
    getHistory(nodeSign) {
      const fc = this.flowContext || {},
        list = fc.handleHistoryList || [],
        result = []
      if (!list.length) {
        return []
      }
      for (let i = 0, len = list.length; i < len; i++) {
        if (list[i].nodeSign === nodeSign) {
          result.push(list[i])
        }
      }
      return result
    }
  },
  computed: {
    zbcgyjList() {
      return this.getHistory("zbcgyj")
    },
  }
}
' WHERE id = 44;
