      let list = this.fieldList || [],
        canEdit = false
      if (!list.length) {
        return false
      }
      // console.log("fieldList",this.fieldList)
      for (let i = 0, len = list.length; i < len; i++) {
        if (list[i].name === fieldName) {
          console.log("list[i]", list[i])
          canEdit = !list[i].disabled
          break
        }
      }
      return canEdit
    },
    getHistory(nodeSign) {
      const fc = this.flowContext || {},
        list = fc.handleHistoryList || [],
        result = []
      if (!list.length) {
        return []
      }
      for (let i = 0, len = list.length; i < len; i++) {
        if (list[i].nodeSign === nodeSign) {
          result.push(list[i])
        }
      }
      return result
    }
  },
