UPDATE ecos_demo.td_nnct_oa_document SET "mobile_template_code" = '{
template: `
		<div class="doc-paper-container">
		
			<div style="display: flex; justify-content: space-between; margin-bottom: 15px;">
				<div>日期：{{ formatTimestamp(payload.formData.createTimestamp)}}</div>
			</div>
		
			<table class="table-paper" style="margin-bottom:2px;">
				<tr>
					<th style="width: 35%">标题</th>
					<td >{{ payload.formData.title }}</td>
				</tr>
				<tr>
					<th>姓名</th>
					<td >{{ payload.formData.applicant }}</td>
				</tr>
				<tr>
					<th>职务</th>
					<td >{{ payload.formData.zw }}</td>
				</tr>
				<tr>
					<th>请示、报告内容（详细填写）</th>
					<td >{{ payload.formData.nr }}</td>
				</tr>
				<tr>
					<th>离岗联系手机</th>
					<td >{{ payload.formData.sj }}</td>
				</tr>
				<tr>
					<th>代为主持工作领导姓名、职务、联系方式</th>
					<td >{{ payload.formData.dwzc }}</td>
				</tr>
				<tr>
				<th>请假天数</th>
				<td >{{ payload.formData.leaveDay }}</td>
			</tr>
			<tr v-if="formatTimestamp( payload.formData.lyStartTime )">
				<th>请假时间</th>
				<td >{{ formatTimestamp( payload.formData.startTime ) }}至{{ formatTimestamp( payload.formData.endTime) }}</td>
			</tr>
				<tr>
					<th>离岗类型</th>
					<td >{{ payload.formData.lglx }}</td>
				</tr>			
				<tr>
					<th>是否离邕</th>
					<td >{{getSelectTypeName(''sfly'')}}</td>
				</tr>
			<tr v-if="payload.formData.sfly === ''1''">
				<th>离邕起止时间</th>
				<td  v-if="formatTimestamp( payload.formData.lyStartTime )">{{ formatTimestamp( payload.formData.lyStartTime ) }}至{{ formatTimestamp( payload.formData.lyEndTime) }}</td>
				<td  v-else>{{ formatTimestamp( payload.formData.startTime ) }}至{{ formatTimestamp( payload.formData.endTime) }}</td>
			</tr>
				<tr>
					<th>离邕地点</th>
					<td >{{ payload.formData.lgdd }}</td>
				</tr>
				<tr>
					<th>相关附件</th>
					<td >
						<template
							v-if="payload.formData && payload.formData.enclosure && payload.formData.enclosure.length">
							<upload-file :disabled="true" :showUploadBar="false" title-class="fs14"
								:upload-file-list="payload.formData.enclosure"></upload-file>
						</template>
					</td>
				</tr>
				<tr>
					<th>关联流程</th>
					<td >
						<template
							v-if="payload.formData && payload.formData.relateFlowList && payload.formData.relateFlowList.length">
							<relate-flow-list :itemData="payload.formData.relateFlowList" />
						</template>
					</td>
				</tr>
				
			<tr>
				<th>集团公司董事长<br/>审批</th>
				<td ><flow-operate-remark-item :list="dszList"></flow-operate-remark-item></td>
			</tr>
			<tr>
				<th>集团公司总经理<br/>审批</th>
				<td ><flow-operate-remark-item :list="fzjlList"></flow-operate-remark-item></td>
			</tr>
			<tr>
				<th>集团公司<br />业务分管领导<br/>审批</th>
				<td ><flow-operate-remark-item :list="jtgsfgldList"></flow-operate-remark-item></td>
			</tr>
			<tr v-if="payload.formData.isThreeLv===''1''&&payload.formData.isNeedTwoLv===''1''">
				<th>相关二级企业<br/>领导审批</th>
				<td ><flow-operate-remark-item :list="twoLvList"></flow-operate-remark-item></td>
			</tr>
			<tr>
				<th>申请{{payload.formData.isThreeLv===''1''&&payload.formData.isNeedTwoLv===''1''?''(三级)'':''''}}企业<br/>法定代表人<br/>审批</th>
				<td ><flow-operate-remark-item :list="qyfzrList"></flow-operate-remark-item></td>
			</tr>
				<tr>
					<th>备注</th>
					<td >{{ payload.formData.bz }}</td>
				</tr>
			</table>
		</div>
	`,
	created(){
			
	},
	methods: {
		formatTimestamp(timestamp) {
			if (timestamp) {
				var date = new Date(timestamp);
				var year = date.getFullYear();
				var month = date.getMonth() + 1;
				var day = date.getDate();
				return year + ''-'' + month + ''-'' + day;
			}
		},
		getSelectTypeName(attrName) {
			const t = this, formData = t.payload.formData, fieldList = t.fieldList || t.payload.fieldList || [], name = ''''   
			
				
			for (let i = 0, len = fieldList.length; i < len; i++) {
				let item = fieldList[i]			
				
				if (item.name === attrName) {					
				const datasource = item.datasource || []
				for (let j = 0, len2 = datasource.length; j < len2; j++) {
					let data = datasource[j]
					if (attrName && data[item.valueField] === formData[attrName]) {
					return data[item.labelField]
					}
				}
				}
			}
			return formData[attrName]
		},    
		getHistory(nodeSign) {
			const fc = this.flowContext || {},
				list = fc.handleHistoryList || [],
				result = []
			
			if (!list.length) {
				return []
			}
			for (let i = 0, len = list.length; i < len; i++) {
				if (list[i].nodeSign === nodeSign) {
					result.push(list[i])
				}
			}
			return result
		}
	},
	computed: {
		twoLvList() {
				let twoDsz = this.getHistory("twoDsz")
				let twoFgldLeader = this.getHistory("twoFgldLeader")
				return [].concat(twoDsz).concat(twoFgldLeader)
			},
		qyfzrList() {
			return this.getHistory("qyfzr")
		},
		jtgsfgldList() {
			return this.getHistory("fgld")
		},
		fzjlList() {
			return this.getHistory("fzjl")
		},
		dszList() {
			return this.getHistory("dsz")
		},
	},
} 	' WHERE id = 7;
