data(){
	return {

	}
},
		methods: {
			getSelectTypeName(attrName) {
				const t = this, formData = t.payload.formData, fieldList = t.fieldList || t.payload.fieldList || [], name = ''''   
				  
				for (let i = 0, len = fieldList.length; i < len; i++) {
					let item = fieldList[i]					
					if (item.name === attrName) {				
					const datasource = item.datasource || []
					for (let j = 0, len2 = datasource.length; j < len2; j++) {
						let data = datasource[j]
						if (attrName && data[item.valueField] === formData[attrName]) {
						return data[item.labelField]
						}
					}
					}
				}
				return formData[attrName]
			},       
			formatTimestamp(timestamp) {
				if (timestamp) {
					var date = new Date(timestamp);
					var year = date.getFullYear();
					var month = date.getMonth() + 1;
					var day = date.getDate();
					return year + ''-'' + month + ''-'' + day;
				}
			},
			getHistory(nodeSign) {
				const fc = this.flowContext || {},
					list = fc.handleHistoryList || [],
					result = []
				if (!list.length) {
					return []
				}
				for (let i = 0, len = list.length; i < len; i++) {
					if (list[i].nodeSign === nodeSign) {
						result.push(list[i])
					}
				}
				console.log("adta",this)
				return result
			}
		},
		computed: {
			twoLvList() {
				let twoDsz = this.getHistory("twoDsz")
				let twoFgldLeader = this.getHistory("twoFgldLeader")
				return [].concat(twoDsz).concat(twoFgldLeader)
			},
			qyfzrList() {
				console.log("this---",this)
				return this.getHistory("qyfzr")
			},
			jtgsfgldList() {
				return this.getHistory("fgld")
			},
			fzjlList() {
				return this.getHistory("fzjl")
			},
			dszList() {
				return this.getHistory("dsz")
			},
		},
} 	' WHERE id = 7;
