    ('td_nnct_oa_http_invoke_log', '9994', 'response_body', '1f68fe5147115dd3aa4b8f5d6739d6c0', '50f502d1a09b907a73ffb157bb0586fe'),
    ('td_nnct_oa_http_invoke_log', '9995', 'request_body', 'feeffc440b41708eebb5105f866692b1', 'bedad91303c12e72a93293984a758ff9')
  ), actual AS (
    SELECT 'td_nnct_oa_http_invoke_log'::text tbl, id::text id, 'response_body'::text col,
           md5(response_body) m FROM ecos_demo.td_nnct_oa_http_invoke_log
    UNION ALL SELECT 'td_nnct_oa_http_invoke_log', id::text, 'request_body',
           md5(request_body) FROM ecos_demo.td_nnct_oa_http_invoke_log
    UNION ALL SELECT 'td_nnct_oa_document', id::text, 'template_code',
           md5(template_code) FROM ecos_demo.td_nnct_oa_document
    UNION ALL SELECT 'td_nnct_oa_document', id::text, 'mobile_template_code',
           md5(mobile_template_code) FROM ecos_demo.td_nnct_oa_document
    UNION ALL SELECT 'td_data_scope_sql_log', id::text, 'original_sql',
           md5(original_sql) FROM ecos_demo.td_data_scope_sql_log
    UNION ALL SELECT 'td_data_scope_sql_log', id::text, 'rewritten_sql',
           md5(rewritten_sql) FROM ecos_demo.td_data_scope_sql_log
  )
  SELECT count(*), count(*) FILTER (WHERE a.m = e.correct_md5),
         count(*) FILTER (WHERE a.m = e.defect_md5)
    INTO v_cells, v_ok, v_defect
    FROM expected e JOIN actual a ON (a.tbl, a.id, a.col) = (e.tbl, e.id, e.col);
  RAISE NOTICE 'md5 逐值比对: cells=%, correct_hit=%, defect_hit=%', v_cells, v_ok, v_defect;
  IF v_cells <> 195 OR v_ok <> 195 OR v_defect <> 0 THEN
    RAISE EXCEPTION 'md5 校验未通过 (cells=%, correct=%, defect=%)', v_cells, v_ok, v_defect;
  END IF;
  SELECT count(*) INTO v_rows_invoke FROM ecos_demo.td_nnct_oa_http_invoke_log;
  SELECT count(*) INTO v_rows_doc FROM ecos_demo.td_nnct_oa_document;
  SELECT count(*) INTO v_rows_scope FROM ecos_demo.td_data_scope_sql_log;
  RAISE NOTICE '行数: invoke_log=%, document=%, scope_sql_log=%',
               v_rows_invoke, v_rows_doc, v_rows_scope;
  IF (v_rows_invoke, v_rows_doc, v_rows_scope) <> (4635, 57, 4177) THEN
    RAISE EXCEPTION '行数校验未通过 (%/%/%)', v_rows_invoke, v_rows_doc, v_rows_scope;
  END IF;
END
$verify$;

COMMIT;
